# O 8 - NANG CAO: chan dau vao ngoai vung du lieu
def du_doan_an_toan(gio, phut):
    if not (0.5 <= gio <= 7.0) or not (15 <= phut <= 450):
        return "Ngoai pham vi du lieu, khong du doan duoc"
    return du_doan(gio, phut)

for gio, phut in [(12, 150), (-3, 100), (4, 1000), (5, 100)]:
    print(gio, phut, "->", du_doan_an_toan(gio, phut))
